/** Localize page-owned UI; never translate code, SDK results, user input or app names. */
export function installPageLanguage(catalogue: Record<string, Record<string, string>>) {
  const normalize = (value: string) => {
    const code = (value || '').toLowerCase().replaceAll('_', '-').split('-')[0];
    return code === 'tl' ? 'fil' : catalogue[code] ? code : '';
  };
  const preferred = normalize(new URL(location.href).searchParams.get('lang') || '') ||
    (navigator.languages || [navigator.language]).map(normalize).find(Boolean) || 'en';
  let locale = preferred;
  const sources = new WeakMap<Node, { source: string; rendered: string }>();
  const attributes = new WeakMap<Element, Map<string, { source: string; rendered: string }>>();
  const english = Object.keys(catalogue.en);
  const patterns = english.filter(key => /\{\w+\}/.test(key)).map(key => ({ key, expression: new RegExp('^' + key.split(/(\{\w+\})/).map(part => /^\{\w+\}$/.test(part) ? '(.+?)' : part.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('') + '$'), parameters: key.match(/\{\w+\}/g)! }));
  function translate(source: string) {
    const words = catalogue[locale] || catalogue.en;
    if (words[source]) return words[source];
    for (const { key, expression, parameters } of patterns) {
      const match = source.match(expression);
      if (match) return parameters.reduce((text, parameter, index) => text.replace(parameter, match[index + 1]), words[key] || key);
    }
    return source;
  }
  function text(node: Node) {
    if (node.nodeType !== 3 || node.parentElement?.closest('script,style,pre,code,textarea,input,[contenteditable],[data-no-translate]')) return;
    const current = node.textContent || '', saved = sources.get(node);
    const source = saved && saved.rendered === current ? saved.source : current;
    const trimmed = source.trim();
    const rendered = trimmed ? source.replace(trimmed, translate(trimmed)) : source;
    sources.set(node, { source, rendered });
    if (current !== rendered) node.textContent = rendered;
  }
  function element(el: Element) {
    if (el.closest('script,style,pre,code,[data-no-translate]')) return;
    for (const name of ['aria-label', 'placeholder', 'title']) {
      const current = el.getAttribute(name); if (!current) continue;
      let saved = attributes.get(el); if (!saved) { saved = new Map(); attributes.set(el, saved); }
      const previous = saved.get(name), source = previous?.rendered === current ? previous.source : current;
      const rendered = translate(source); saved.set(name, { source, rendered });
      if (current !== rendered) el.setAttribute(name, rendered);
    }
  }
  function walk(root: Node) {
    if (root.nodeType === 3) { text(root); return; }
    if (root instanceof Element) element(root);
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT);
    let node; while ((node = walker.nextNode())) { if (node instanceof Element) element(node); else text(node); }
  }
  function setLanguage(value: string) {
    locale = normalize(value) || 'en';
    document.documentElement.lang = locale;
    document.documentElement.dir = locale === 'ar' ? 'rtl' : 'ltr';
    walk(document.documentElement);
  }
  setLanguage(preferred);
  const observer = new MutationObserver(records => {
    if (records.some(record => record.type === 'attributes' && record.target === document.documentElement && record.attributeName === 'lang')) {
      const next = normalize(document.documentElement.lang) || 'en';
      if (next !== locale) { setLanguage(next); return; }
    }
    for (const record of records) {
      if (record.type === 'characterData') text(record.target);
      else if (record.type === 'childList') record.addedNodes.forEach(walk);
      else if (record.target instanceof Element) element(record.target);
    }
  });
  observer.observe(document.documentElement, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ['lang', 'aria-label', 'placeholder', 'title'] });
  return { translate, setLanguage, language: () => locale, dispose: () => observer.disconnect() };
}

